"""Day 17 SVG diagrams extracted and preserved from HEAD."""

FIG_17_1_HTML = '<figure class="diagram-container diagram-figure">\n<p class="diagram-scroll-hint">Swipe horizontally to view the full diagram.</p>\n<svg aria-labelledby="day17-trace-title day17-trace-desc" role="img" viewbox="0 0 940 360">\n<title id="day17-trace-title">Gate 1 End-to-End Foundation Request and Execution Trace</title>\n<desc id="day17-trace-desc">Comprehensive architectural request flow tracing a client checkout through DNS resolution, IP subnet routing, TLS termination, containerized execution, Twelve-Factor application handling, and relational ACID persistence with duplicate fulfillment protection.</desc>\n<defs>\n<marker id="day17-flow-arrow" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#38bdf8"></path></marker>\n<marker id="day17-pass-arrow" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#22c55e"></path></marker>\n</defs>\n<!-- Main Container Box -->\n<g fill="#121526" stroke="#475569" stroke-width="1.5">\n<rect height="315" rx="8" width="900" x="20" y="25"></rect>\n</g>\n<g fill="#f8fafc" font-size="11" font-weight="700">\n<text x="35" y="47">BLOCK 1 FOUNDATION RECALL: THE COMPLETE REQUEST LIFECYCLE</text>\n<text fill="#a9b7cb" font-size="9" font-weight="400" x="35" y="63">Tracing client checkout from DNS through Linux containers to ACID database persistence (Days 1–16)</text>\n</g>\n<!-- Stage 1: DNS & Client (Days 3-4) -->\n<g font-size="9">\n<rect fill="#1e293b" height="150" rx="5" stroke="#38bdf8" width="130" x="35" y="80"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="98">1. CLIENT &amp; DNS</text>\n<text fill="#a9b7cb" x="45" y="112">Days 3 &amp; 4</text>\n<rect fill="#090d16" height="35" rx="3" stroke="#334155" width="110" x="45" y="120"></rect>\n<text fill="#e2e8f0" x="50" y="133">DNS A Record</text>\n<text fill="#38bdf8" x="50" y="146">api.brightloaf.internal</text>\n<rect fill="#090d16" height="55" rx="3" stroke="#334155" width="110" x="45" y="162"></rect>\n<text fill="#e2e8f0" x="50" y="177">HTTP/1.1 POST</text>\n<text fill="#a9b7cb" x="50" y="190">TLS 1.3 Handshake</text>\n<text fill="#22c55e" x="50" y="203">X-Request-ID gen</text>\n<path d="M165,155 L190,155" marker-end="url(#day17-flow-arrow)" stroke="#38bdf8" stroke-width="1.5"></path>\n<!-- Stage 2: Network & Subnet (Day 2) -->\n<rect fill="#1e293b" height="150" rx="5" stroke="#38bdf8" width="130" x="190" y="80"></rect>\n<text fill="#38bdf8" font-weight="700" x="200" y="98">2. TCP/IP ROUTING</text>\n<text fill="#a9b7cb" x="200" y="112">Day 2 CIDR / OSI</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="110" x="200" y="120"></rect>\n<text fill="#e2e8f0" x="205" y="133">Client: 10.0.1.50</text>\n<text fill="#e2e8f0" x="205" y="146">Subnet: /24</text>\n<text fill="#a9b7cb" x="205" y="158">Gateway: 10.0.1.1</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="110" x="200" y="172"></rect>\n<text fill="#e2e8f0" x="205" y="187">Dest: 10.0.2.10:443</text>\n<text fill="#22c55e" x="205" y="200">Non-overlapping</text>\n<text fill="#a9b7cb" x="205" y="211">L3/L4 Packet Fwd</text>\n<path d="M320,155 L345,155" marker-end="url(#day17-flow-arrow)" stroke="#38bdf8" stroke-width="1.5"></path>\n<!-- Stage 3: Container & Host (Days 5, 8, 9, 10) -->\n<rect fill="#1e293b" height="150" rx="5" stroke="#38bdf8" width="145" x="345" y="80"></rect>\n<text fill="#38bdf8" font-weight="700" x="355" y="98">3. LINUX &amp; DOCKER</text>\n<text fill="#a9b7cb" x="355" y="112">Days 5, 8, 9, 10</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="125" x="355" y="120"></rect>\n<text fill="#e2e8f0" x="360" y="133">Port 8080:8080</text>\n<text fill="#a9b7cb" x="360" y="146">Bridge Network</text>\n<text fill="#e2e8f0" x="360" y="158">iptables NAT rule</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="125" x="355" y="172"></rect>\n<text fill="#e2e8f0" x="360" y="187">cgroups: 512MB RAM</text>\n<text fill="#e2e8f0" x="360" y="200">Namespaces (net,pid)</text>\n<text fill="#22c55e" x="360" y="211">Non-root user (10001)</text>\n<path d="M490,155 L515,155" marker-end="url(#day17-flow-arrow)" stroke="#38bdf8" stroke-width="1.5"></path>\n<!-- Stage 4: 12-Factor App (Day 15) -->\n<rect fill="#1e293b" height="150" rx="5" stroke="#38bdf8" width="140" x="515" y="80"></rect>\n<text fill="#38bdf8" font-weight="700" x="525" y="98">4. 12-FACTOR APP</text>\n<text fill="#a9b7cb" x="525" y="112">Day 15 Architecture</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="120" x="525" y="120"></rect>\n<text fill="#e2e8f0" x="530" y="133">Env Config (PORT)</text>\n<text fill="#e2e8f0" x="530" y="146">Schema Validation</text>\n<text fill="#22c55e" x="530" y="158">HTTP 422 on error</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="120" x="525" y="172"></rect>\n<text fill="#e2e8f0" x="530" y="187">Structured JSON</text>\n<text fill="#a9b7cb" x="530" y="200">Unbuffered stdout</text>\n<text fill="#38bdf8" x="530" y="211">Trace context pass</text>\n<path d="M655,155 L680,155" marker-end="url(#day17-flow-arrow)" stroke="#38bdf8" stroke-width="1.5"></path>\n<!-- Stage 5: SQL & ACID (Day 16) -->\n<rect fill="#1e293b" height="150" rx="5" stroke="#22c55e" stroke-width="1.5" width="225" x="680" y="80"></rect>\n<text fill="#22c55e" font-weight="700" x="690" y="98">5. ACID RELATIONAL STATE</text>\n<text fill="#a9b7cb" x="690" y="112">Day 16 3NF &amp; Invariants</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#334155" width="205" x="690" y="120"></rect>\n<text fill="#38bdf8" x="695" y="133">BEGIN TRANSACTION;</text>\n<text fill="#e2e8f0" x="695" y="146">INSERT orders, items (3NF)</text>\n<text fill="#22c55e" x="695" y="158">Atomic Commit / Rollback</text>\n<rect fill="#090d16" height="45" rx="3" stroke="#22c55e" width="205" x="690" y="172"></rect>\n<text fill="#22c55e" font-weight="700" x="695" y="187">order_fulfillments.order_id</text>\n<text fill="#22c55e" x="695" y="200">UNIQUE constraint enforces</text>\n<text fill="#fce7f3" x="695" y="211">&lt;= 1 physical shipment invariant</text>\n<!-- Summary Check Banner at bottom -->\n<rect fill="#090d16" height="75" rx="5" stroke="#334155" width="870" x="35" y="245"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="265">GATE 1 ACCEPTANCE CHECKLIST (Days 1–16 Integrated Proof):</text>\n<text fill="#e2e8f0" x="45" y="282">✓ DNS &amp; HTTP: Request resolved via explicit A records and parsed with strict JSON schema validation.</text>\n<text fill="#e2e8f0" x="45" y="297">✓ Linux &amp; Docker: Executed as non-root user in isolated container with memory cgroups and verified port forwarding.</text>\n<text fill="#22c55e" font-weight="700" x="45" y="312">✓ State &amp; Invariants: Atomic transaction rollback prevents orphaned records; relational UNIQUE constraint guarantees &lt;= 1 fulfillment.</text>\n</g>\n</svg>\n<figcaption>Figure 17.1: Gate 1 end-to-end foundation request and execution trace. The diagram unifies the core architectural concepts mastered in Block 1 (Days 1–16): DNS lookup and HTTP/TLS intake, non-overlapping subnet routing, non-root Linux container execution, Twelve-Factor application validation with structured JSON logging, and atomic relational transactions backed by schema-level constraints guaranteeing the duplicate fulfillment invariant.</figcaption>\n</figure>'

FIG_17_2_HTML = '<figure class="diagram-container diagram-figure">\n<p class="diagram-scroll-hint">Swipe horizontally to view the full diagram.</p>\n<svg aria-labelledby="day17-rubric-title day17-rubric-desc" role="img" viewbox="0 0 940 330">\n<title id="day17-rubric-title">Five-Dimension Foundation Rubric and Gate 1 Decision Flow</title>\n<desc id="day17-rubric-desc">Evaluation matrix illustrating the five evaluation dimensions (Correctness, Traceability, Evidence Quality, Recovery Reasoning, Communication) scored from 0 to 3, paired with the Gate 1 decision tree determining passage to Block 2 or targeted remediation.</desc>\n<defs>\n<marker id="day17-rubric-arrow" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#38bdf8"></path></marker>\n<marker id="day17-pass-gate" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#22c55e"></path></marker>\n<marker id="day17-fail-gate" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#f43f5e"></path></marker>\n</defs>\n<!-- Left Panel: 5 Dimensions -->\n<g fill="#121526" stroke="#475569" stroke-width="1.5">\n<rect height="285" rx="8" width="460" x="20" y="25"></rect>\n</g>\n<g fill="#f8fafc" font-size="11" font-weight="700">\n<text x="35" y="47">FIVE-DIMENSION EVALUATION RUBRIC</text>\n<text fill="#a9b7cb" font-size="9" font-weight="400" x="35" y="63">Score 0 (Absent), 1 (Partial), 2 (Adequate with limits), 3 (Defensible)</text>\n</g>\n<g font-size="9">\n<!-- Dim 1 -->\n<rect fill="#1e293b" height="38" rx="4" stroke="#334155" width="430" x="35" y="78"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="93">1. Correctness:</text>\n<text fill="#e2e8f0" x="135" y="93">Subnet CIDRs, SQL foreign keys, and port bindings mathematically sound.</text>\n<text fill="#a9b7cb" x="45" y="106">Threshold: Zero unhandled syntax errors or overlapping network ranges.</text>\n<!-- Dim 2 -->\n<rect fill="#1e293b" height="38" rx="4" stroke="#334155" width="430" x="35" y="122"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="137">2. Traceability:</text>\n<text fill="#e2e8f0" x="145" y="137">Every config option traces directly to roadmap requirements.</text>\n<text fill="#a9b7cb" x="45" y="150">Threshold: Clear link between Twelve-Factor rules and operational outcomes.</text>\n<!-- Dim 3 -->\n<rect fill="#1e293b" height="38" rx="4" stroke="#334155" width="430" x="35" y="166"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="181">3. Evidence Quality:</text>\n<text fill="#e2e8f0" x="165" y="181">Timestamped terminal logs, exit codes, and assertions saved.</text>\n<text fill="#a9b7cb" x="45" y="194">Threshold: Reproducible by an independent reviewer without external state.</text>\n<!-- Dim 4 -->\n<rect fill="#1e293b" height="38" rx="4" stroke="#334155" width="430" x="35" y="210"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="225">4. Recovery Reasoning:</text>\n<text fill="#e2e8f0" x="185" y="225">Predicts failure mode and verifies clean rollback.</text>\n<text fill="#a9b7cb" x="45" y="238">Threshold: Upholds duplicate fulfillment invariant across retry/replay.</text>\n<!-- Dim 5 -->\n<rect fill="#1e293b" height="42" rx="4" stroke="#334155" width="430" x="35" y="254"></rect>\n<text fill="#38bdf8" font-weight="700" x="45" y="269">5. Communication:</text>\n<text fill="#e2e8f0" x="165" y="269">Concise business framing (Cloud Digital Leader alignment).</text>\n<text fill="#a9b7cb" x="45" y="282">Threshold: Separates observed facts from tabletop design models.</text>\n</g>\n<!-- Right Panel: Decision Tree -->\n<g fill="#121526" stroke="#475569" stroke-width="1.5">\n<rect height="285" rx="8" width="420" x="500" y="25"></rect>\n</g>\n<g fill="#f8fafc" font-size="11" font-weight="700">\n<text x="515" y="47">GATE 1 EVALUATION &amp; REMEDIATION FLOW</text>\n<text fill="#a9b7cb" font-size="9" font-weight="400" x="515" y="63">Decision boundary for Block 2 (Cloud Environment &amp; Identity)</text>\n</g>\n<g font-size="9">\n<!-- Box 1: Audit -->\n<rect fill="#1e293b" height="40" rx="4" stroke="#38bdf8" width="390" x="515" y="80"></rect>\n<text fill="#38bdf8" font-weight="700" x="525" y="96">EVIDENCE AUDIT</text>\n<text fill="#e2e8f0" x="525" y="110">Review Day 5 (Linux), Day 8 (Containers), Day 10 (Net), Day 16 (SQL)</text>\n<path d="M710,120 L710,145" marker-end="url(#day17-rubric-arrow)" stroke="#38bdf8" stroke-width="1.5"></path>\n<!-- Diamond / Condition Box -->\n<rect fill="#090d16" height="40" rx="4" stroke="#f59e0b" stroke-width="1.5" width="330" x="545" y="145"></rect>\n<text fill="#f59e0b" font-weight="700" text-anchor="middle" x="710" y="162">All 5 dimensions &gt;= 2 AND Total &gt;= 12/15?</text>\n<text fill="#a9b7cb" text-anchor="middle" x="710" y="176">Correct explanations and zero unhandled errors required</text>\n<!-- Pass Path (Green) -->\n<path d="M545,165 L525,165 L525,230 L555,230" marker-end="url(#day17-pass-gate)" stroke="#22c55e" stroke-width="2"></path>\n<rect fill="#052e16" height="75" rx="4" stroke="#22c55e" stroke-width="1.5" width="160" x="555" y="210"></rect>\n<text fill="#22c55e" font-weight="700" x="565" y="228">PASS · PROCEED TO G2</text>\n<text fill="#dcfce7" x="565" y="242">Block 1 Foundations Cleared</text>\n<text fill="#e2e8f0" x="565" y="258">Advance to Day 18:</text>\n<text fill="#38bdf8" x="565" y="271">Cloud Environment &amp; IAM</text>\n<!-- Remediate Path (Red) -->\n<path d="M875,165 L895,165 L895,230 L870,230" marker-end="url(#day17-fail-gate)" stroke="#f43f5e" stroke-width="2"></path>\n<rect fill="#3b1d38" height="75" rx="4" stroke="#f43f5e" stroke-width="1.5" width="175" x="730" y="210"></rect>\n<text fill="#f43f5e" font-weight="700" x="740" y="228">REMEDIATE / REPEAT</text>\n<text fill="#fce7f3" x="740" y="242">Weak dimension identified</text>\n<text fill="#e2e8f0" x="740" y="258">Repair specific lab gap</text>\n<text fill="#f59e0b" x="740" y="271">Re-score before Day 18</text>\n</g>\n</svg>\n<figcaption>Figure 17.2: Five-dimension evaluation rubric and Gate 1 decision flow. The framework grades foundational mastery across Correctness, Traceability, Evidence Quality, Recovery Reasoning, and Communication. Achieving adequate proficiency (score ≥ 2 in each dimension, ≥ 12/15 overall) authorizes advancement to Block 2 (Cloud environment and identity); failing scores trigger targeted remediation of the specific foundation gap without introducing unneeded cloud services.</figcaption>\n</figure>'

FIG_17_3_HTML = '<figure class="diagram-container diagram-figure">\n<p class="diagram-scroll-hint">Swipe horizontally to view the full diagram.</p>\n<svg aria-labelledby="day17-inc1-title day17-inc1-desc" role="img" viewbox="0 0 940 330">\n<title id="day17-inc1-title">Incident Diagram: Overlapping CIDR Subnets and DNS Conflict Remediation</title>\n<desc id="day17-inc1-desc">Diagnostic incident diagram illustrating how overlapping 10.0.1.0/24 IP subnets and DNS search domain loops caused microservice connection timeouts, contrasted with explicit non-overlapping CIDR blocks and authoritative private DNS resolution.</desc>\n<defs>\n<marker id="day17-fail-arrow" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#f43f5e"></path></marker>\n<marker id="day17-corr-arrow" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#22c55e"></path></marker>\n</defs>\n<!-- Left Boundary: Service Intake -->\n<g fill="#121526" stroke="#475569" stroke-width="1.5">\n<rect height="280" rx="8" width="170" x="20" y="25"></rect>\n</g>\n<g fill="#f8fafc" font-size="10" font-weight="700" text-anchor="middle">\n<text x="105" y="50">ORDER SERVICE INTAKE</text>\n<text fill="#a9b7cb" font-size="9" font-weight="400" x="105" y="65">Microservice Container</text>\n</g>\n<g font-size="9">\n<rect fill="#1e293b" height="55" rx="4" stroke="#334155" width="150" x="30" y="80"></rect>\n<text fill="#e2e8f0" x="40" y="100">connect("db.internal")</text>\n<text fill="#38bdf8" x="40" y="115">X-Request-ID: "req-17-01"</text>\n<text fill="#a9b7cb" x="40" y="127">TCP Port 5432</text>\n</g>\n<!-- FAILED PATH (Top) -->\n<g fill="#121526" stroke="#f43f5e" stroke-width="1.5">\n<rect height="130" rx="8" width="700" x="220" y="25"></rect>\n</g>\n<g fill="#f43f5e" font-size="10" font-weight="700">\n<text x="235" y="47">[FAILED PATH: Overlapping 10.0.1.0/24 CIDR &amp; search domain loop]</text>\n</g>\n<g font-size="9">\n<!-- Step 1: DNS Loop -->\n<rect fill="#1e293b" height="55" rx="4" stroke="#f43f5e" stroke-width="1.5" width="190" x="235" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="245" y="78">1. DNS Search Domain Loop</text>\n<text fill="#fce7f3" x="245" y="92">db.internal.order.svc.cluster...</text>\n<text fill="#f59e0b" x="245" y="105">NXDOMAIN delays + loop</text>\n<path d="M425,87 L460,87" marker-end="url(#day17-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<!-- Step 2: Routing Collision -->\n<rect fill="#1e293b" height="55" rx="4" stroke="#f43f5e" stroke-width="1.5" width="200" x="460" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="470" y="78">2. Subnet Collision (10.0.1.0/24)</text>\n<text fill="#fce7f3" x="470" y="92">Order Pod: 10.0.1.15</text>\n<text fill="#fce7f3" x="470" y="105">Database Subnet: 10.0.1.0/24</text>\n<path d="M660,87 L690,87" marker-end="url(#day17-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<!-- Step 3: Timeout Failure -->\n<rect fill="#3b1d38" height="85" rx="4" stroke="#f43f5e" width="215" x="690" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="700" y="78">CRITICAL OUTAGE</text>\n<text fill="#fce7f3" x="700" y="92">• Packet loops locally to eth0</text>\n<text fill="#fce7f3" x="700" y="106">• Database host unreachable</text>\n<text fill="#fce7f3" x="700" y="120">• 10,000 ms connection timeout</text>\n<text fill="#fce7f3" x="700" y="134">• Checkout halts; cart drop-off</text>\n</g>\n<!-- Connect Intake to Failed -->\n<path d="M180,105 L220,87" marker-end="url(#day17-fail-arrow)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<!-- CORRECTED PATH (Bottom) -->\n<g fill="#121526" stroke="#22c55e" stroke-width="1.5">\n<rect height="130" rx="8" width="700" x="220" y="175"></rect>\n</g>\n<g fill="#22c55e" font-size="10" font-weight="700">\n<text x="235" y="197">[CORRECTED PATH: Distinct CIDR subnets &amp; authoritative split-horizon DNS]</text>\n</g>\n<g font-size="9">\n<!-- Step 1: Explicit FQDN -->\n<rect fill="#1e293b" height="55" rx="4" stroke="#334155" width="190" x="235" y="210"></rect>\n<text fill="#38bdf8" font-weight="700" x="245" y="228">1. Authoritative FQDN Resolution</text>\n<text fill="#e2e8f0" x="245" y="242">db.production.brightloaf.internal</text>\n<text fill="#22c55e" x="245" y="255">A record: 10.20.1.10 (&lt;2 ms)</text>\n<path d="M425,237 L460,237" marker-end="url(#day17-corr-arrow)" stroke="#22c55e" stroke-width="2"></path>\n<!-- Step 2: Non-overlapping CIDR -->\n<rect fill="#1e293b" height="55" rx="4" stroke="#334155" width="200" x="460" y="210"></rect>\n<text fill="#38bdf8" font-weight="700" x="470" y="228">2. Disjoint RFC 1918 Subnets</text>\n<text fill="#e2e8f0" x="470" y="242">Order VPC: 10.10.1.0/24</text>\n<text fill="#e2e8f0" x="470" y="255">Database VPC: 10.20.1.0/24</text>\n<path d="M660,237 L690,237" marker-end="url(#day17-corr-arrow)" stroke="#22c55e" stroke-width="2"></path>\n<!-- Step 3: Verified Persistence -->\n<rect fill="#052e16" height="85" rx="4" stroke="#22c55e" width="215" x="690" y="210"></rect>\n<text fill="#22c55e" font-weight="700" x="700" y="228">STABLE COMMUNICATION</text>\n<text fill="#dcfce7" x="700" y="242">✓ Predictable L3 next-hop routing</text>\n<text fill="#dcfce7" x="700" y="256">✓ TCP handshake in 1.4 ms</text>\n<text fill="#dcfce7" x="700" y="270">✓ Atomic SQL transaction commit</text>\n<text fill="#dcfce7" x="700" y="284">✓ Duplicate fulfillment suppressed</text>\n</g>\n<!-- Connect Intake to Corrected -->\n<path d="M180,120 L220,237" marker-end="url(#day17-corr-arrow)" stroke="#22c55e" stroke-width="2"></path>\n</svg>\n<figcaption>Figure 17.3: Supplied facts: Microservice deployment encountered repeated 10,000 ms database connection timeouts during order intake despite application code compiling cleanly. Architectural inference: Overlapping RFC 1918 CIDR allocations (10.0.1.0/24 in both pod network and database tier) combined with wildcard DNS search domains caused routing loops and packet dropping. Expected post-fix behavior: Re-architecting into disjoint subnets (10.10.1.0/24 and 10.20.1.0/24) paired with authoritative FQDN resolution establishes deterministic next-hop routing and restores sub-2 ms database connectivity.</figcaption>\n</figure>'

FIG_17_4_HTML = '<figure class="diagram-container diagram-figure">\n<p class="diagram-scroll-hint">Swipe horizontally to view the full diagram.</p>\n<svg aria-labelledby="day17-inc2-title day17-inc2-desc" role="img" viewbox="0 0 940 330">\n<title id="day17-inc2-title">Incident Diagram: Unchecked Event Replay Breaches Duplicate Fulfillment Invariant</title>\n<desc id="day17-inc2-desc">Diagnostic incident diagram illustrating how message redelivery without relational unique constraints caused duplicate physical shipments, contrasted with a database-level idempotent gatekeeper enforcing the duplicate fulfillment invariant.</desc>\n<defs>\n<marker id="day17-replay-fail" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#f43f5e"></path></marker>\n<marker id="day17-replay-corr" markerheight="7" markerwidth="9" orient="auto" refx="8" refy="3.5"><path d="M0,0 L9,3.5 L0,7 Z" fill="#22c55e"></path></marker>\n</defs>\n<!-- Left Box: Event Replay Stream -->\n<g fill="#121526" stroke="#475569" stroke-width="1.5">\n<rect height="280" rx="8" width="180" x="20" y="25"></rect>\n</g>\n<g fill="#f8fafc" font-size="10" font-weight="700" text-anchor="middle">\n<text x="110" y="50">EVENT STREAM REPLAY</text>\n<text fill="#a9b7cb" font-size="9" font-weight="400" x="110" y="65">Order Event: BL-17-901</text>\n</g>\n<g font-size="9">\n<rect fill="#1e293b" height="55" rx="4" stroke="#334155" width="160" x="30" y="80"></rect>\n<text fill="#e2e8f0" x="40" y="98">Event 1: T=00:00:01</text>\n<text fill="#38bdf8" x="40" y="112">Order BL-17-901 Created</text>\n<text fill="#22c55e" x="40" y="125">Payload: Sourdough x2</text>\n<rect fill="#1e293b" height="55" rx="4" stroke="#f59e0b" width="160" x="30" y="150"></rect>\n<text fill="#f59e0b" font-weight="700" x="40" y="168">Event 2: T=00:00:15 (Replay)</text>\n<text fill="#fce7f3" x="40" y="182">Network ACK timeout retry</text>\n<text fill="#f59e0b" x="40" y="195">Identical Order BL-17-901</text>\n</g>\n<!-- FAILED PATH (Top) -->\n<g fill="#121526" stroke="#f43f5e" stroke-width="1.5">\n<rect height="130" rx="8" width="690" x="230" y="25"></rect>\n</g>\n<g fill="#f43f5e" font-size="10" font-weight="700">\n<text x="245" y="47">[FAILED PATH: Naive event consumer without database uniqueness guard]</text>\n</g>\n<g font-size="9">\n<rect fill="#1e293b" height="60" rx="4" stroke="#f43f5e" width="200" x="245" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="255" y="78">1. Process Event 1</text>\n<text fill="#e2e8f0" x="255" y="92">Generates Shipping Label</text>\n<text fill="#22c55e" x="255" y="105">Fulfillment ful-001 created</text>\n<path d="M445,90 L480,90" marker-end="url(#day17-replay-fail)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<rect fill="#1e293b" height="60" rx="4" stroke="#f43f5e" width="200" x="480" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="490" y="78">2. Process Event 2 (Replay)</text>\n<text fill="#fce7f3" x="490" y="92">No schema deduplication!</text>\n<text fill="#f43f5e" x="490" y="105">Fulfillment ful-002 created</text>\n<path d="M680,90 L710,90" marker-end="url(#day17-replay-fail)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<rect fill="#3b1d38" height="85" rx="4" stroke="#f43f5e" width="195" x="710" y="60"></rect>\n<text fill="#f43f5e" font-weight="700" x="720" y="78">INVARIANT VIOLATED</text>\n<text fill="#fce7f3" x="720" y="92">• 2 physical boxes shipped!</text>\n<text fill="#fce7f3" x="720" y="106">• Inventory doubled depleted</text>\n<text fill="#fce7f3" x="720" y="120">• 100% shipping cost loss</text>\n<text fill="#fce7f3" x="720" y="134">• Direct Gate 1 safety failure</text>\n</g>\n<!-- Connect Intake to Failed -->\n<path d="M190,175 L230,90" marker-end="url(#day17-replay-fail)" stroke="#f43f5e" stroke-dasharray="7 5" stroke-width="2"></path>\n<!-- CORRECTED PATH (Bottom) -->\n<g fill="#121526" stroke="#22c55e" stroke-width="1.5">\n<rect height="130" rx="8" width="690" x="230" y="175"></rect>\n</g>\n<g fill="#22c55e" font-size="10" font-weight="700">\n<text x="245" y="197">[CORRECTED PATH: Relational UNIQUE(order_id) constraint idempotency guard]</text>\n</g>\n<g font-size="9">\n<rect fill="#1e293b" height="60" rx="4" stroke="#334155" width="200" x="245" y="210"></rect>\n<text fill="#38bdf8" font-weight="700" x="255" y="228">1. Process Event 1</text>\n<text fill="#e2e8f0" x="255" y="242">INSERT INTO order_fulfillments</text>\n<text fill="#22c55e" x="255" y="255">Committed: ful-BL-17-901</text>\n<path d="M445,240 L480,240" marker-end="url(#day17-replay-corr)" stroke="#22c55e" stroke-width="2"></path>\n<rect fill="#1e293b" height="60" rx="4" stroke="#22c55e" width="200" x="480" y="210"></rect>\n<text fill="#22c55e" font-weight="700" x="490" y="228">2. Process Event 2 (Replay)</text>\n<text fill="#f59e0b" x="490" y="242">UNIQUE constraint catches dup</text>\n<text fill="#22c55e" x="490" y="255">Catches sqlite3.IntegrityError</text>\n<path d="M680,240 L710,240" marker-end="url(#day17-replay-corr)" stroke="#22c55e" stroke-width="2"></path>\n<rect fill="#052e16" height="85" rx="4" stroke="#22c55e" width="195" x="710" y="210"></rect>\n<text fill="#22c55e" font-weight="700" x="720" y="228">INVARIANT PRESERVED</text>\n<text fill="#dcfce7" x="720" y="242">✓ Exactly 1 physical shipment</text>\n<text fill="#dcfce7" x="720" y="256">✓ Duplicate suppressed cleanly</text>\n<text fill="#dcfce7" x="720" y="270">✓ Returns HTTP 200 idempotent</text>\n<text fill="#dcfce7" x="720" y="284">✓ Gate 1 proof validated</text>\n</g>\n<!-- Connect Intake to Corrected -->\n<path d="M190,185 L230,240" marker-end="url(#day17-replay-corr)" stroke="#22c55e" stroke-width="2"></path>\n</svg>\n<figcaption>Figure 17.4: Supplied facts: An asynchronous message queue delivered an order fulfillment event twice due to an upstream network acknowledgement timeout, causing a naive consumer to generate two physical warehouse shipments. Architectural inference: Network delivery cannot guarantee exactly-once processing; idempotency must be enforced at the relational persistence boundary. Expected post-fix behavior: Utilizing a UNIQUE(order_id) constraint on the fulfillment table rejects replayed events with an integrity error, suppressing duplicate shipments and strictly preserving the ≤ 1 fulfillment invariant.</figcaption>\n</figure>'

